cypress_script:
describe('Multi-level Navigation Menu', () => {
  it('should navigate to Sub Item under Main Item 1', () => {
    cy.visit('https://demoqa.com/menu');
    cy.contains('Main Item 1').click();
    cy.contains('Sub Item').should('be.visible');
    cy.url().should('include', '/menu');
  });

  it('should not change URL when clicking on a non-link item', () => {
    cy.visit('https://demoqa.com/menu');
    cy.contains('Main Item 1').click();
    cy.contains('Sub Sub Item 1').click();
    cy.url().should('include', '/menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-level Navigation Menu', () => {
  test('should navigate to Sub Item under Main Item 1', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('text=Main Item 1');
    await expect(page.locator('text=Sub Item')).toBeVisible();
    await expect(page).toHaveURL(/.*menu/);
  });

  test('should not change URL when clicking on a non-link item', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('text=Main Item 1');
    await page.click('text=Sub Sub Item 1');
    await expect(page).toHaveURL(/.*menu/);
  });
});
